                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == v and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append((v, cells))

    # Small marks identify the color to transfer to the nearest larger object.
    marks = [(v, cells) for v, cells in comps if len(cells) <= 2]
    objects = [(v, cells) for v, cells in comps if len(cells) > 2]
    if not marks or not objects:
        return [row[:] for row in grid]

    best = None
    for color, mark in marks:
        for old, obj in objects:
            if old == color:
                continue
            d = min(abs(r-y) + abs(c-x) for r, c in mark for y, x in obj)
            if best is None or d < best[0]:
                best = (d, color, obj)

    out = [row[:] for row in grid]
    if best:
        _, color, obj = best
        for r, c in obj:
            out[r][c] = color
    return out
