def transform(grid):
    from collections import deque
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    # Markers of color 1 identify the object to recolor as color 1.
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v in (bg, 1) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == v and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            comps.append(cells)
    if not marks or not comps:
        return [row[:] for row in grid]
    # Avoid selecting the object adjacent to a marker; use the closest component
    # by component bounding-box distance.
    def dist(cells):
        return min(abs(r-y) + abs(c-x) for r, c in cells for y, x in marks)
    target = min(comps, key=dist)
    out = [row[:] for row in grid]
    for r, c in target:
        out[r][c] = 1
    return out
